package com.example.code.controller

import com.example.code.data.LotteryCreationRepository
import com.example.code.data.lotteryFromMap
import com.example.code.data.newLotteryToMap
import com.example.code.fakes.FakeReservationRepository
import com.example.code.model.Campsite
import com.example.code.model.Lottery
import com.example.code.model.LotteryCampsite
import com.example.code.model.Reservation
import com.example.code.model.WaitingListEntry
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Test

// === US 02.04.02: BEGIN multiple campsite unit tests ===
class MultiCampsiteLotteryTest {
    private val ownerId = "owner-device"
    private val first = Campsite(id = "site-1", ownerId = ownerId, name = "Pine Creek")
    private val second = Campsite(id = "site-2", ownerId = ownerId, name = "River Bend")
    private val settings = Lottery(
        registrationStart = 1_000L,
        registrationEnd = 2_000L,
        bookingStart = 3_000L,
        bookingEnd = 4_000L,
        winnerCount = 2,
    )

    private class RecordingCreator : LotteryCreationRepository {
        val saved = mutableListOf<Lottery>()
        override suspend fun createLottery(lottery: Lottery): String {
            saved += lottery
            return "created-lottery"
        }
    }

    private suspend fun publishGroup(): Lottery {
        val repository = RecordingCreator()
        LotteryController.publishLottery(repository, listOf(first, second), ownerId, settings)
        return repository.saved.single().copy(id = "created-lottery")
    }

    @Test
    fun publishesOneLotteryContainingBothOwnedCampsites() = runBlocking {
        val repository = RecordingCreator()
        LotteryController.publishLottery(
            repository,
            listOf(first, second),
            ownerId,
            settings.copy(
                ownerId = "spoofed-owner",
                waitingListCount = 20,
                status = Lottery.STATUS_DRAWN,
                winnerIds = listOf("old-winner"),
            ),
        )
        val saved = repository.saved.single()
        assertEquals(ownerId, saved.ownerId)
        assertEquals(first.id, saved.campsiteId)
        assertEquals(
            listOf(LotteryCampsite(first.id, first.name), LotteryCampsite(second.id, second.name)),
            saved.campsites,
        )
        assertEquals(settings.registrationStart, saved.registrationStart)
        assertEquals(settings.registrationEnd, saved.registrationEnd)
        assertEquals(settings.bookingStart, saved.bookingStart)
        assertEquals(settings.bookingEnd, saved.bookingEnd)
        assertEquals(settings.winnerCount, saved.winnerCount)
        assertEquals(0, saved.waitingListCount)
        assertEquals(Lottery.STATUS_OPEN, saved.status)
        assertTrue(saved.winnerIds.isEmpty())
    }

    @Test
    fun rejectsEmptyDuplicateAndOtherOwnersSelections() {
        val invalidSelections = listOf(
            emptyList<Campsite>(),
            listOf(first, first),
            listOf(first, second.copy(ownerId = "another-owner")),
        )
        invalidSelections.forEach { selected ->
            val repository = RecordingCreator()
            assertThrows(IllegalArgumentException::class.java) {
                runBlocking {
                    LotteryController.publishLottery(repository, selected, ownerId, settings)
                }
            }
            assertTrue(repository.saved.isEmpty())
        }
    }

    @Test
    fun multipleCampsitesSurviveFirestoreMapping() = runBlocking {
        val lottery = publishGroup()
        val fields = newLotteryToMap(lottery)
        assertTrue(fields.containsKey("campsites"))
        assertEquals(lottery, lotteryFromMap(lottery.id, fields))
    }

    @Test
    fun existingSingleCampsiteDocumentsRemainCompatible() = runBlocking {
        val repository = RecordingCreator()
        LotteryController.publishLottery(repository, first, ownerId, settings)
        val saved = repository.saved.single()
        val fields = newLotteryToMap(saved)
        val restored = lotteryFromMap("legacy-lottery", fields)
        assertFalse(fields.containsKey("campsites"))
        assertEquals(
            listOf(LotteryCampsite(first.id, first.name)),
            LotteryController.includedCampsites(restored),
        )
    }

    @Test
    fun sameLotteryIsFoundFromEitherCampsite() = runBlocking {
        val lottery = publishGroup()
        assertEquals(lottery, WaitingListController.lotteryForCampsite(listOf(lottery), first.id))
        assertEquals(lottery, WaitingListController.lotteryForCampsite(listOf(lottery), second.id))
        assertNull(WaitingListController.lotteryForCampsite(listOf(lottery), "unrelated-site"))
    }

    @Test
    fun bookingOneCampsiteDoesNotHideTheOtherFromDateFilters() = runBlocking {
        val controller = CampsiteFilterController()
        val selection = controller.parse("", "", "2027-05-14", "2027-05-16")
        val stay = selection.stay!!
        val lottery = publishGroup().copy(bookingStart = stay.start, bookingEnd = stay.end)
        val booked = Reservation(campsiteId = second.id, startDate = stay.start, endDate = stay.end)
        val results = controller.apply(
            campsites = listOf(first, second),
            selection = selection,
            lotteries = listOf(lottery),
            reservations = listOf(booked),
        )
        assertEquals(listOf(first), results)
    }

    @Test
    fun winnerReservesSelectedCampsiteAndCannotAcceptTwice() = runBlocking {
        val repository = FakeReservationRepository()
        val controller = ReservationController(repository) { 2_500L }
        val lottery = publishGroup().copy(status = Lottery.STATUS_DRAWN)
        val winner = WaitingListEntry(
            entrantId = "entrant-device",
            entrantName = "Priya",
            status = WaitingListEntry.STATUS_WON,
        )
        val reservation = controller.acceptWin(lottery, winner, second.id)
        assertNotNull(reservation)
        assertEquals(second.id, reservation!!.campsiteId)
        assertEquals(second.name, reservation.campsiteName)
        assertEquals(lottery.bookingStart, reservation.startDate)
        assertEquals(lottery.bookingEnd, reservation.endDate)
        assertNull(controller.acceptWin(lottery, winner, first.id))
    }

    @Test
    fun winnerCannotReserveACampsiteOutsideTheLottery() {
        assertThrows(IllegalArgumentException::class.java) {
            runBlocking {
                val controller = ReservationController(FakeReservationRepository())
                val lottery = publishGroup().copy(status = Lottery.STATUS_DRAWN)
                val winner = WaitingListEntry(
                    entrantId = "entrant-device",
                    status = WaitingListEntry.STATUS_WON,
                )
                controller.acceptWin(lottery, winner, "unrelated-site")
            }
        }
    }
}
// === US 02.04.02: END multiple campsite unit tests ===
